import os
import re

def process_ini_files(target_dir, exclude_dir):
    processed_count = 0
    modified_count = 0
    errors = []

    for root, dirs, files in os.walk(target_dir):
        # 'yedek' klasörünü atla
        if os.path.normpath(root) == os.path.normpath(exclude_dir):
            continue

        for file in files:
            if not file.endswith('.ini'):
                continue

            file_path = os.path.join(root, file)

            try:
                # Dosyayı binary modda oku
                with open(file_path, 'rb') as f:
                    raw_data = f.read()

                if not raw_data:
                    continue

                # BOM kontrolü
                bom = b''
                if raw_data.startswith(b'\xef\xbb\xbf'):
                    bom = b'\xef\xbb\xbf'
                elif raw_data.startswith(b'\xff\xfe'):
                    bom = b'\xff\xfe'
                elif raw_data.startswith(b'\xfe\xff'):
                    bom = b'\xfe\xff'

                # Satır sonlarını tespit et
                if b'\r\n' in raw_data:
                    line_terminator = b'\r\n'
                elif b'\n' in raw_data:
                    line_terminator = b'\n'
                else:
                    line_terminator = b'' # Tek satır veya boş dosya durumu için

                # İçeriği satırlara ayır (BOM'dan sonrasını)
                content_part = raw_data[len(bom):]
                if not line_terminator:
                    # Dosya sadece tek satırsa
                    lines = [content_part]
                    has_trailing_newline = False
                else:
                    lines = content_part.split(line_terminator)
                    # split() son boş satırı boş string olarak verir eğer dosya sonu newline ile bitiyorsa
                    if not lines[-1]:
                        has_trailing_newline = True
                        lines.pop()
                    else:
                        has_trailing_newline = False

                new_lines = []
                in_target_section = False
                modified = False

                # Regexler:
                # Bölüm kontrolü: [section_name]
                # Port kontrolü: port = 5432 (boşluklar serbest)
                section_regex = re.compile(b'^\[([^\]]+)\]', re.IGNORECASE)
                # (boşluklar)(port)(boşluklar)=(boşluklar)(5432)(boşluklar)
                port_regex = re.compile(b'^(\s*port\s*=\s*)(5432)(\s*)$', re.IGNORECASE)

                for line in lines:
                    # Mevcut satır bir bölüm başlığı mı?
                    section_match = re.match(b'^\[([^\]]+)\]', line)
                    if section_match:
                        section_name = section_match.group(1).decode('utf-8', errors='ignore').lower()
                        if section_name == 'veritabani':
                            in_target_section = True
                        else:
                            in_target_section = False

                    # Değişiklik kontrolü
                    if in_target_section:
                        match = port_regex.match(line)
                        if match:
                            # match.group(1) = prefix (e.g. "  port  =")
                            # match.group(2) = "5432"
                            # match.group(3) = suffix (e.g. "  ")
                            new_line = match.group(1) + b'6543' + match.group(3)
                            if line != new_line:
                                line = new_line
                                modified = True

                    new_lines.append(line)

                if modified:
                    # Yedek al
                    with open(file_path + '.bak', 'wb') as f:
                        f.write(raw_data)

                    # Yeni içeriği yaz
                    with open(file_path, 'wb') as f:
                        f.write(bom)
                        for i, nl in enumerate(new_lines):
                            f.write(nl)
                            if i < len(new_lines) - 1 or has_trailing_newline:
                                f.write(line_terminator)

                    modified_count += 1

                processed_count += 1

            except Exception as e:
                errors.append(f"{file_path}: {str(e)}")

    return processed_count, modified_count, errors

if __name__ == "__main__":
    p, m, e = process_ini_files('servisler', 'servisler/yedek')
    print(f"PROCESSED:{p}")
    print(f"MODIFIED:{m}")
    if e:
        print("ERRORS:")
        for err in e:
            print(f" - {err}")

